{"money.py":"from decimal import Decimal, ROUND_HALF_UP

def total_cents(items):
    total = Decimal(0)
    for item in items:
        total += Decimal(item["price"]) * int(item["qty"])
    cents = (total * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    return int(cents)

def format_cents(cents):
    sign = "-" if cents < 0 else ""
    abs_cents = abs(cents)
    return f"{sign}{abs_cents // 100}.{abs_cents % 100:02d}"
